import { isColliding, isCollidingForced, stopPlayer } from '~/game/util/collision'
import { emitKickImpact, emitMoveBomb } from '~/services/socket'

interface BombProps {
  axes: [number, number]
  id?: string
  player?: Player
  playerIndex: number
  reach: number
  x?: number
  y?: number
  detonationMultiplier?: number
}

export interface Bomb {
  anim          : AnimControl['anim']
  armed         : boolean
  blast         : Blast
  collidable    : boolean
  detonated     : boolean
  detonateTime  : number
  directions    : Directions
  finalPosition : number
  flinging      : boolean
  holding       : boolean
  id            : string
  moving        : boolean
  kickMode      : LinearMutation
  kickInitiator : number
  kickAuthority : boolean
  player       ?: Player
  playerIndex   : number
  ownerIndex    : number // Dono original, mesmo após outro jogador segurar
  reach         : number
  removeTime    : number
  detonationMultiplier: number
  side          : SIDES
  x             : number
  y             : number
  moves  : {[key in SIDES]:(state:GameState) => void}
  flings : {[key in SIDES]:(state:GameState) => void}
  getAxes              : () => [number, number]
  setDetonation        : (multiplier?:number) => void
  detonate             : (state:GameState) => void
  checkPlayerCollision : (state:GameState) => void
  startMove            : (side:SIDES, state:GameState, mode?:LinearMutation, kicker?:number) => boolean
  stopMove             : (state:GameState) => void
  setHolding           : (playerIndex:number, state:GameState) => void
  startFling           : (side:SIDES) => void
  moveBuffKick          : (state:GameState) => void
  tick                 : (state:GameState) => void
  render               : (context:CanvasRenderingContext2D) => void
}

export function BombFactory (props : BombProps) : Bomb {
  const bomb:Bomb = props as unknown as Bomb
  if (props.player) {
    bomb.id = `O${Math.floor(Math.random() * 9999999)}`
    bomb.x = (props.axes[1] + 1) * TILE_SIZE || TILE_SIZE
    bomb.y = (props.axes[0] + 1) * TILE_SIZE || TILE_SIZE
  }
  bomb.anim = {frameCurrent:0, lastRender:0, sum:true}
  bomb.ownerIndex = props.playerIndex
  bomb.armed = true
  bomb.detonated = false
  bomb.detonationMultiplier = props.detonationMultiplier ??
    (props.player?.hasOverclock ? OVERCLOCK_DETONATION_MULTIPLIER : 1)
  bomb.blast = BlastFactory()
  bomb.collidable = false
  bomb.directions = {up:0, right:0, down:0, left:0}
  bomb.holding = false
  bomb.moving = false
  bomb.kickMode = 'normal'
  bomb.kickInitiator = -1
  bomb.kickAuthority = false
  bomb.moves = {'D':moveDown.bind(bomb), 'U':moveUp.bind(bomb), 'R':moveRight.bind(bomb), 'L':moveLeft.bind(bomb)}
  bomb.flings = {'D':flingDown.bind(bomb), 'U':flingUp.bind(bomb), 'R':flingRight.bind(bomb), 'L':flingLeft.bind(bomb)}
  bomb.getAxes = getAxes.bind(bomb)
  bomb.setDetonation = setDetonation.bind(bomb)
  bomb.detonate = detonate.bind(bomb)
  bomb.checkPlayerCollision = checkPlayerCollision.bind(bomb)
  bomb.startMove = startMove.bind(bomb)
  bomb.moveBuffKick = moveBuffKick.bind(bomb)
  bomb.stopMove = stopMove.bind(bomb)
  bomb.setHolding = setHolding.bind(bomb)
  bomb.startFling = startFling.bind(bomb)
  bomb.tick = tick.bind(bomb)
  bomb.render = render.bind(bomb)
  bomb.setDetonation()
  return bomb
}

function getAxes (this:Bomb) : [number, number] {
  const x = Math.round(this.y / TILE_SIZE) - 1
  const y = Math.round(this.x / TILE_SIZE) - 1
  return [x, y]
}

function setDetonation (this:Bomb, multiplier=1) {
  this.detonateTime = Date.now() + (3000 * this.detonationMultiplier * multiplier)
  this.removeTime = this.detonateTime + 500
}

function detonate (this:Bomb, state:GameState) {
  // Pode explodir por timer OU por cascata. Garante execução única em ambos.
  if (!this.armed) return
  this.armed = false
  this.detonated = true
  // Uma bomba pode explodir pelo timer enquanto ainda desliza.
  // Não continuar movendo a animação nem recolocar uma bomba já detonada
  // no mapa depois da explosão (especialmente no chute com vírus).
  this.moving = false
  this.flinging = false
  this.removeTime = Date.now() + 500
  // O retorno da bomba ao arsenal do dono não depende mais do timer.
  if (this.player) this.player.bombs++
  playBlastSound()
  if (this.holding) {
    if (this.playerIndex === state.players.myself!.index) {
      state.players.myself!.kill(true, 'bomb')
    }
    this.stopMove(state)
  }
  const holder = state.players.players[this.playerIndex]
  // O jogador não pode continuar em modo 'segurando' depois da detonação.
  if (holder?.bombId === this.id) {
    holder.holding = 0
    holder.bombId = ''
  }

  const [ax, ay] = this.getAxes()
  // Alcance 0 sai dos quatro loops antes de limpar a casa central.
  // Remover o marcador 'O' do próprio explosivo evita a célula fantasma
  // que fazia holdBomb/flingBomb acessar uma bomba já removida.
  const center = state.blocks.getBlock([ax, ay])
  if (center?.t === 'O' && center.id === this.id) {
    state.blocks.destroyBlock([ax, ay])
  }
  for (let i = ax; i > -1; i--) {
    if (this.directions.up === this.reach) break
    const b = state.blocks.getBlock([i, ay])
    if (!b) this.directions.up++
    else if (b.t === 'D') {
      b.destroy()
      break
    }
    else if (b.t === 'I') break
    else {
      this.directions.up++
      state.blocks.destroyBlock([i, ay])
    }
  }
  for (let i = ay; i < 13; i++) {
    if (this.directions.right === this.reach) break
    const b = state.blocks.getBlock([ax, i])
    if (!b) this.directions.right++
    else if (b.t === 'D') {
      b.destroy()
      break
    }
    else if (b.t === 'I') break
    else {
      this.directions.right++
      state.blocks.destroyBlock([ax, i])
    }
  }
  for (let i = ax; i < 11; i++) {
    if (this.directions.down === this.reach) break
    const b = state.blocks.getBlock([i, ay])
    if (!b) this.directions.down++
    else if (b.t === 'D') {
      b.destroy()
      break
    }
    else if (b.t === 'I') break
    else {
      this.directions.down++
      state.blocks.destroyBlock([i, ay])
    }
  }
  for (let i = ay; i > -1; i--) {
    if (this.directions.left === this.reach) break
    const b = state.blocks.getBlock([ax, i])
    if (!b) this.directions.left++
    else if (b.t === 'D') {
      b.destroy()
      break
    }
    else if (b.t === 'I') break
    else {
      this.directions.left++
      state.blocks.destroyBlock([ax, i])
    }
  }

  // Só após calcular os quatro raios (com todas as paredes ainda no lugar)
  // verifica outras bombas reais da partida. Isso inclui as bombas de
  // adversários, que não precisam existir como blocos 'O' neste cliente.
  const armedBombs: ArmedBombPosition[] = []
  for (const entity of state.entities.entities.values()) {
    const candidate = entity as Partial<Bomb>
    if (typeof candidate.getAxes !== 'function' ||
        typeof candidate.detonate !== 'function' ||
        typeof candidate.armed !== 'boolean') continue

    armedBombs.push({
      id: entity.id,
      axes: candidate.getAxes(),
      armed: candidate.armed
    })
  }

  const targets = findChainReactionTargets(
    this.id, [ax, ay], this.directions, armedBombs
  )

  // A flag 'armed=false' é aplicada antes da recursão. Mesmo que
  // A -> B -> C -> A, cada bomba explode uma vez, sem loop infinito.
  for (const id of targets) {
    const target = state.entities.get(id) as Bomb | undefined
    if (target?.armed) target.detonate(state)
  }
}

function checkPlayerCollision (this:Bomb, state:GameState) {
  const [px, py] = state.players.myself!.getAxes()
  const [ax, ay] = this.getAxes()
  for (let i = this.directions.up - 1; i > -1; i--) {
    if (px === ax - i && py === ay) {
      state.players.myself!.kill(true, 'bomb')
      return
    }
  }
  for (let i = this.directions.down - 1; i > -1; i--) {
    if (px === ax + i && py === ay) {
      state.players.myself!.kill(true, 'bomb')
      return
    }
  }
  for (let i = this.directions.left - 1; i > -1; i--) {
    if (px === ax && py === ay - i) {
      state.players.myself!.kill(true, 'bomb')
      return
    }
  }
  for (let i = this.directions.right - 1; i > -1; i--) {
    if (px === ax && py === ay + i) {
      state.players.myself!.kill(true, 'bomb')
      return
    }
  }
}
